// header
{
  "alg": "RS256",
  "typ": "JWT",
  "kid": "auth-key-2026-03"
}
// payload (authorization claims are scope + tenant + role)
{
  "iss": "https://auth.internal",
  "aud": "orders-api",
  "sub": "user_9f31",
  "tenant": "acme",
  "scope": "orders:read orders:write",
  "role": "support-agent",
  "iat": 1757145600,
  "exp": 1757145900
}
// wire form: base64url(header).base64url(payload).signature

import jwt  # PyJWT

# Pin everything. No dynamic alg, no optional aud.
PUBLIC_KEY = open("auth-key-2026-03.pem").read()

def authorize(request_headers, required_scope: str):
    token = request_headers["Authorization"].removeprefix("Bearer ")
    try:
        claims = jwt.decode(
            token,
            PUBLIC_KEY,
            algorithms=["RS256"],  # allowlist, never trust header alg
            issuer="https://auth.internal",
            audience="orders-api",
            leeway=60,  # clock skew tolerance
            options={"require": ["exp", "iss", "aud", "sub"]},
        )
    except jwt.ExpiredSignatureError:
        return (401, "expired")
    except jwt.InvalidTokenError:
        return (401, "invalid")

    scopes = set(claims.get("scope", "").split())
    if required_scope not in scopes:
        return (403, "insufficient scope")
    # Trade-off: tenant/object check still needs app data.
    # Token gives you tenant id; ownership join happens here.
    if claims.get("tenant") != request_headers.get("X-Tenant"):
        return (403, "tenant mismatch")
    return (200, claims)
